import json,subprocess,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];a=json.loads((R/'config-v14/horses.lock.json').read_text())['assets'][0];dest=R/'work/v14-pin';cmd=[sys.executable,str(R/'scripts/pin_horses_v14.py'),'--id',a['asset_id'],'--version',a['version'],'--sha256',a['model_sha256'],'--dest',str(dest),'--review-candidate','--include-mother'];subprocess.run(cmd,check=True);r=subprocess.run(cmd,capture_output=True,text=True);assert r.returncode!=0 and 'overwriting' in r.stdout+r.stderr
bad=cmd.copy();bad[bad.index('--sha256')+1]='0'*64;bad[bad.index('--dest')+1]=str(R/'work/v14-bad-pin');r=subprocess.run(bad,capture_output=True,text=True);assert r.returncode!=0 and not (R/'work/v14-bad-pin').exists()
comparison=json.loads((R/'config-v14/horses.lock.json').read_text())['comparison_assets'][0];trial=cmd.copy();trial[trial.index('--id')+1]=comparison['asset_id'];trial[trial.index('--sha256')+1]=comparison['model_sha256'];trial[trial.index('--dest')+1]=str(R/'work/v14-trial-pin');result=subprocess.run(trial,capture_output=True,text=True);assert result.returncode!=0 and not (R/'work/v14-trial-pin').exists()
(R/'evidence-v14/pin-check.json').write_text(json.dumps({'exact_id_version_sha':True,'editable_mother_included':True,'existing_destination_rejected':True,'wrong_sha_rejected':True,'v13_comparison_not_republished_as_v14':True,'game_ready':False},indent=2)+'\n');print('PIN_PASS')
